CREATE TABLE liquidaciones.accounting_exports(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id uuid,modification_group_id uuid,remittance_id bigint,member_id bigint,export_type text NOT NULL,file_path text NOT NULL,info_file_path text,status text NOT NULL,line_count integer NOT NULL DEFAULT 0,excluded_line_count integer NOT NULL DEFAULT 0,net_total numeric(18,6),amount_total numeric(18,6),file_hash varchar(64),source_fingerprint varchar(64),generated_at timestamptz,created_at timestamptz NOT NULL,created_by text,error_message text,generation_attempt integer NOT NULL DEFAULT 1,supersedes_export_id bigint REFERENCES liquidaciones.accounting_exports(id),batch_ids_json jsonb);
CREATE TABLE liquidaciones.accounting_export_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,export_id bigint NOT NULL REFERENCES liquidaciones.accounting_exports(id),batch_id uuid NOT NULL REFERENCES liquidaciones.liquidation_batches(batch_id),liquidation_id bigint REFERENCES liquidaciones.liquidaciones(id),recipient_member_id bigint,operation_type varchar(16),created_at timestamptz NOT NULL,UNIQUE(export_id,liquidation_id));
